create table work_items (
 id bigint generated by default as identity primary key, kind varchar(20) not null check(kind in ('TASK','LEAVE','REPORT')),
 owner_id bigint not null references users(id), client_id bigint references saccos(id),
 subject varchar(180) not null, description varchar(4000) not null, start_at timestamp not null, end_at timestamp not null,
 work_type varchar(100) not null default '', outcome varchar(30) not null default '', explanation varchar(4000) not null default '',
 allowance numeric(14,2) not null default 0 check(allowance>=0), amount numeric(14,2) not null default 0 check(amount>=0),
 status varchar(30) not null check(status in ('DRAFT','PLANNED','IN_PROGRESS','COMPLETED','CANCELLED','SUBMITTED','APPROVED','REJECTED')),
 review_comment varchar(1000) not null default '', reviewed_by bigint references users(id), reviewed_at timestamptz,
 created_by bigint not null references users(id), request_key uuid not null, version bigint not null default 0,
 created_at timestamptz not null default current_timestamp, updated_at timestamptz not null default current_timestamp,
 check(end_at>=start_at), unique(created_by,kind,request_key), check(reviewed_by is null or reviewed_by<>owner_id)
);
create index work_owner_kind_idx on work_items(owner_id,kind,id desc);
create index work_kind_status_date_idx on work_items(kind,status,start_at,id);
insert into work_items(kind,owner_id,client_id,subject,description,start_at,end_at,work_type,allowance,amount,status,created_by,request_key,created_at)
select 'TASK',t.user_id,t.saccos_id,tt.name,coalesce(t.activities,''),t.start_date,t.end_date,tt.name,t.allowance,t.amount,upper(s.status_name),t.user_id,md5('legacy-task-'||t.id)::uuid,t.created_date from tasks t join task_types tt on tt.id=t.task_type_id join task_status s on s.id=t.task_status_id;
